import React from "react";

function Pricing() {
  return (
    <div className="page">
      <h1>Pricing Plans</h1>
      <p>Choose the best plan for you:</p>
      <ul>
        <li>💰 Basic - Free</li>
        <li>💰 Premium - $9.99/month</li>
        <li>💰 Pro - $19.99/month</li>
      </ul>
    </div>
  );
}

export default Pricing;
